<?php
namespace AutoDealership\Admin;
use AutoDealership\Inventory\InventoryWorkspace;
use AutoDealership\Database\Schema;
use AutoDealership\Pricing\Money;
use AutoDealership\Pricing\PublicVehiclePrice;
use AutoDealership\Security\BranchScope;
defined('ABSPATH') || exit;

final class InventoryWorkspacePage {
	private static function t(string $ar,string $en):string{return \AutoDealership\Core\Localization::language()==='en'?$en:$ar;}
	private static function url(array $args=array()):string{return add_query_arg(array_merge(array('page'=>'adc-inventory'),$args),admin_url('admin.php'));}
	public static function render():void {
		if(!current_user_can('adc_view_inventory')){wp_die('Forbidden','',array('response'=>403));}
		$filters=array();foreach(array('search','brand','model','trim_name','model_year','warehouse_name','availability','completion','operational_status','branch_id','conflicts','paged')as$key){$filters[$key]=sanitize_text_field(wp_unslash($_GET[$key]??''));}if(!$filters['availability']){$filters['availability']='available';}if($filters['conflicts']==='1'){$filters['availability']='all';}
		$result=InventoryWorkspace::list($filters);
		echo '<div class="wrap adc-inventory-workspace" dir="'.(\AutoDealership\Core\Localization::language()==='en'?'ltr':'rtl').'"><h1>'.esc_html(self::t('إدارة السيارات','Vehicle management')).'</h1><p>'.esc_html(self::t('المخزون والتوفر والأسعار من آخر ملف أونكس. استكمل رقم الهيكل الكامل والفرع لبدء الاستلام والفحص والعمليات التجارية.','Inventory, availability and prices come from the latest Onyx file. Complete the full VIN and branch to begin receipt, inspection and commercial operations.')).'</p>';
		if(isset($_GET['saved'])){echo '<div class="notice notice-success"><p>'.esc_html(self::t('تم حفظ العملية.','Operation saved.')).'</p></div>';}
		if(isset($_GET['error'])){echo '<div class="notice notice-error"><p>'.esc_html(self::t('تعذر حفظ العملية. راجع البيانات والصلاحيات والتوفر.','Unable to save. Review data, permissions and availability.')).'</p></div>';}
		echo '<p>';if(current_user_can('adc_manage_inventory')){echo '<a class="button" href="'.esc_url(self::url(array('new'=>1))).'">'.esc_html(self::t('إضافة سيارة خارج أونكس','Add a vehicle outside Onyx')).'</a> ';}echo '<a class="button" href="'.esc_url(self::url(array('legacy'=>1))).'">'.esc_html(self::t('السجلات التشغيلية','Operational records')).'</a> ';if(current_user_can('edit_cars')){echo '<a class="button" href="'.esc_url(CatalogPublishingPage::url()).'">'.esc_html(self::t('سيارات الموقع','Website vehicles')).'</a>';}echo '</p>';
		echo '<form method="get" class="adc-inventory-filters"><input type="hidden" name="page" value="adc-inventory"><div style="display:flex;gap:12px;flex-wrap:wrap">';
		foreach(array('search'=>self::t('بحث الهيكل والسيارة','Chassis / vehicle search'),'brand'=>self::t('الماركة','Brand'),'model'=>self::t('الطراز','Model'),'trim_name'=>self::t('الفئة','Trim'),'model_year'=>self::t('الموديل','Model year'),'warehouse_name'=>self::t('المخزن','Warehouse'))as$key=>$label){echo '<label>'.esc_html($label).'<br><input name="'.$key.'" value="'.esc_attr($filters[$key]).'"></label>';}
		foreach(array('availability'=>array('available'=>self::t('المخزون الحالي','Current inventory'),'sold'=>self::t('المباعة حسب أونكس','Sold according to Onyx'),'all'=>self::t('كل السجلات','All records')),'completion'=>array(''=>self::t('كل مستويات الاستكمال','All completion levels'),'pending'=>self::t('تحتاج استكمال','Needs completion'),'complete'=>self::t('مرتبطة بسجل تشغيلي','Linked operational record')),'operational_status'=>array(''=>self::t('كل الحالات التشغيلية','All operational states'),'received'=>'received','inspection'=>'inspection','available'=>'available','reserved'=>'reserved','sold'=>'sold','hold'=>'hold','maintenance'=>'maintenance'),'conflicts'=>array(''=>self::t('كل التعاملات','All transactions'),'1'=>self::t('غائبة ولها تعامل مفتوح','Absent with an open transaction')))as$key=>$options){echo '<label><select name="'.$key.'" aria-label="'.esc_attr($key).'">';foreach($options as$value=>$label){echo '<option value="'.esc_attr($value).'" '.selected($filters[$key],$value,false).'>'.esc_html(\AutoDealership\Core\Localization::label($label)).'</option>';}echo '</select></label>';}
		$branches=\AutoDealership\Branches\BranchService::public_list();echo '<label><select name="branch_id" aria-label="'.esc_attr(self::t('الفرع','Branch')).'"><option value="">'.esc_html(self::t('كل الفروع المسموحة','All allowed branches')).'</option>';foreach($branches as$branch){if(BranchScope::allows((int)$branch['id'])){echo '<option value="'.(int)$branch['id'].'" '.selected($filters['branch_id'],(string)$branch['id'],false).'>'.esc_html($branch['name']).'</option>';}}echo '</select></label>';
		echo '<button class="button">'.esc_html(self::t('عرض النتائج','Show results')).'</button><a class="button" href="'.esc_url(self::url()).'">'.esc_html(self::t('إعادة ضبط','Reset')).'</a></div></form>';
		if(is_wp_error($result)){echo '<p role="alert">'.esc_html(self::t('تعذر تحميل المخزون. أعد المحاولة.','Unable to load inventory. Retry.')).'</p></div>';return;}
		echo '<p>'.esc_html(sprintf(self::t('عدد السيارات المطابقة: %d','Matching vehicles: %d'),$result['total'])).'</p><div style="overflow:auto"><table class="widefat striped adc-inventory-table"><thead><tr>';
		foreach(array(self::t('الهيكل','Chassis'),self::t('الماركة','Brand'),self::t('الطراز','Model'),self::t('الفئة','Trim'),self::t('اللون','Color'),self::t('الموديل','Model year'),self::t('سعر أونكس قبل الضريبة','Onyx price before VAT'),self::t('سعر الموقع شامل الضريبة واللوحات','Website price including VAT and plates'),self::t('المورد','Supplier'),self::t('المخزن / الفرع','Warehouse / branch'),self::t('ملاحظات','Notes'),self::t('اللون الداخلي','Interior color'),self::t('عمر المخزون','Stock age'),self::t('حالة أونكس','Onyx status'),self::t('الحالة التشغيلية','Operational state'),self::t('الإجراءات','Actions'))as$label){echo '<th scope="col">'.esc_html($label).'</th>';}
		echo '</tr></thead><tbody>';foreach($result['rows']as$row){self::row($row);}if(!$result['rows']){$active_filters=false;foreach(array('search','brand','model','trim_name','model_year','warehouse_name','completion','operational_status','branch_id','conflicts')as$key){if($filters[$key]!==''){$active_filters=true;}}echo '<tr><td colspan="16">';InventoryListState::render($result,'',true,$active_filters);echo '</td></tr>';}echo '</tbody></table></div>';
		if($result['pages']>1){echo '<nav aria-label="'.esc_attr(self::t('صفحات المخزون','Inventory pages')).'">'.wp_kses_post(paginate_links(array('base'=>str_replace('99999999','%#%',self::url(array_merge($filters,array('paged'=>99999999)))),'format'=>'','current'=>$result['page'],'total'=>$result['pages']))).'</nav>';}
		if(current_user_can('manage_options')){self::mapping();}echo '</div>';
	}
	private static function row(array $row):void {
		$id=(int)$row['vehicle_id'];$post=(int)$row['public_post_id'];$price=PublicVehiclePrice::calculate((int)$row['listed_price'],$post);
		echo '<tr>';foreach(array($row['source_identifier'],$row['brand'],$row['model'],$row['trim_name'],$row['exterior_color'],$row['model_year'],Money::display((int)$row['listed_price']),Money::display($price['final_amount']),$row['supplier_name'],$row['warehouse_name'].($row['branch_id']?' / #'.$row['branch_id']:''),$row['notes'],$row['interior_color'],$row['stock_age'])as$value){echo '<td>'.esc_html((string)$value).'</td>';}
		echo '<td>'.esc_html($row['present']?self::t('موجودة في آخر ملف','Present in latest file'):self::t('مباعة حسب أونكس','Sold according to Onyx')).'</td><td>'.esc_html($id?\AutoDealership\Core\Localization::label($row['operational_status']):self::t('تحتاج استكمال','Needs completion')).'</td><td>';
		if($id){echo '<a class="button" href="'.esc_url(add_query_arg(array('page'=>'adc-vehicle-specifications','vehicle_id'=>$id),admin_url('admin.php'))).'">'.esc_html(self::t('التفاصيل','Details')).'</a> ';if(current_user_can('adc_manage_inventory')){echo '<a class="button" href="'.esc_url(add_query_arg(array('page'=>'adc-inventory-identity','vehicle_id'=>$id,'section'=>$row['operational_status']==='inspection'?'inspection':'receipt'),admin_url('admin.php'))).'">'.esc_html(self::t('الاستلام والفحص','Receipt and inspection')).'</a> ';}if($row['present']&&$row['operational_status']==='available'&&current_user_can('adc_create_quotes')){echo '<a class="button" href="'.esc_url(add_query_arg(array('page'=>'adc-sales-journey','vehicle_search'=>$row['stock_number']),admin_url('admin.php'))).'">'.esc_html(self::t('عرض سعر وحجز','Quote and reservation')).'</a> ';}}
		elseif($row['present']&&current_user_can('adc_manage_inventory')){echo '<a class="button" href="'.esc_url(self::url(array('new'=>1,'source_id'=>$row['id']))).'">'.esc_html(self::t('استكمال البيانات','Complete details')).'</a> ';}
		if($post&&current_user_can('edit_post',$post)){echo '<a class="button" href="'.esc_url(CatalogPublishingPage::url($post)).'">'.esc_html(self::t('تحرير صفحة الموقع','Edit website page')).'</a>';}echo '</td></tr>';
	}
	private static function mapping():void {
		global $wpdb;$names=$wpdb->get_col('SELECT DISTINCT warehouse_name FROM '.Schema::table('onyx_stock')." WHERE warehouse_name<>'' ORDER BY warehouse_name");$map=InventoryWorkspace::warehouse_branches();
		echo '<details><summary>'.esc_html(self::t('ربط مخازن أونكس بالفروع','Map Onyx warehouses to branches')).'</summary><p>'.esc_html(self::t('الربط يحدد نطاق عرض السجلات غير المستكملة ويقترح الفرع عند الاستكمال. لا ينقل السيارات المرتبطة بين الفروع.','Mappings scope incomplete stock and suggest its branch during completion. Linked vehicles are not transferred.')).'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="adc_inventory_map">';wp_nonce_field('adc_inventory_map');echo '<input type="hidden" name="revision" value="'.esc_attr(hash('sha256',wp_json_encode($map))).'">';
		$branches=\AutoDealership\Branches\BranchService::public_list();foreach($names??array()as$name){echo '<p><label>'.esc_html($name).' <select name="warehouses['.esc_attr($name).']"><option value="0">'.esc_html(self::t('غير مربوط','Unmapped')).'</option>';foreach($branches as$branch){echo '<option value="'.(int)$branch['id'].'" '.selected($map[$name]??0,$branch['id'],false).'>'.esc_html($branch['name']).'</option>';}echo '</select></label></p>';}echo '<button class="button">'.esc_html(self::t('حفظ ربط المخازن','Save warehouse mappings')).'</button></form></details>';
	}
	public static function save_mapping(array $input) {
		global $wpdb;if(!current_user_can('manage_options')||!current_user_can('adc_manage_inventory')){return new \WP_Error('adc_forbidden','Forbidden');}
		$next=array();if(!is_array($input['warehouses']??null)){return new \WP_Error('adc_invalid','Invalid mappings');}
		$names=$wpdb->get_col('SELECT DISTINCT warehouse_name FROM '.Schema::table('onyx_stock'));if($wpdb->last_error){return new \WP_Error('adc_read','Unavailable');}
		foreach($input['warehouses']as$name=>$branch){if(!in_array($name,$names,true)||!is_scalar($branch)||!ctype_digit((string)$branch)){return new \WP_Error('adc_invalid','Invalid warehouse');}$id=(int)$branch;if($id&&!\AutoDealership\Inventory\VehicleService::branch_exists($id)){return new \WP_Error('adc_invalid','Invalid branch');}if($id){$next[$name]=$id;}}
		add_option('adc_onyx_warehouse_branches',array(),'',false);if(!\AutoDealership\Database\Transaction::begin()){return new \WP_Error('adc_storage','Unavailable');}
		$stored=$wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s FOR UPDATE",'adc_onyx_warehouse_branches'));$old=maybe_unserialize($stored);$old=is_array($old)?$old:array();
		if(!is_string($input['revision']??null)||!hash_equals(hash('sha256',wp_json_encode($old)),$input['revision'])){$wpdb->query('ROLLBACK');return new \WP_Error('adc_stale','Reload mappings before saving');}
		$ok=$wpdb->update($wpdb->options,array('option_value'=>maybe_serialize($next)),array('option_name'=>'adc_onyx_warehouse_branches'))!==false&&\AutoDealership\Database\Transaction::commit(static fn()=>\AutoDealership\Audit\AuditLog::record('inventory.warehouses_mapped','configuration',0,'Onyx warehouse branch mapping',$old,$next));
		if(!$ok){$wpdb->query('ROLLBACK');}wp_cache_delete('adc_onyx_warehouse_branches','options');wp_cache_delete('alloptions','options');return $ok?array('saved'=>true):new \WP_Error('adc_storage','Unable to save');
	}
	public static function submit_mapping():void {check_admin_referer('adc_inventory_map');$result=self::save_mapping(wp_unslash($_POST));wp_safe_redirect(self::url(array(is_wp_error($result)?'error':'saved'=>1)));exit;}
}
